-- Core order-management schema.
CREATE TABLE ORDER_APP.CUSTOMERS (
  CUSTOMER_ID   NUMBER NOT NULL,
  NAME          VARCHAR2(200) NOT NULL,
  REGION_CODE   VARCHAR2(10),
  CREATED_ON    DATE DEFAULT SYSDATE,
  CONSTRAINT CUSTOMERS_PK PRIMARY KEY (CUSTOMER_ID)
);

CREATE TABLE ORDER_APP.ORDERS (
  ORDER_ID      NUMBER NOT NULL,
  CUSTOMER_ID   NUMBER NOT NULL,
  STATUS_CODE   VARCHAR2(20),
  ORDER_TOTAL   NUMBER(12,2),
  CREATED_ON    DATE DEFAULT SYSDATE,
  CONSTRAINT ORDERS_PK PRIMARY KEY (ORDER_ID)
);

CREATE TABLE ORDER_APP.ORDER_LINES (
  LINE_ID       NUMBER NOT NULL,
  ORDER_ID      NUMBER NOT NULL,
  PRODUCT_CODE  VARCHAR2(30),
  QUANTITY      NUMBER,
  CONSTRAINT ORDER_LINES_PK PRIMARY KEY (LINE_ID)
);

CREATE TABLE ORDER_APP.AUDIT_LOG (
  AUDIT_ID      NUMBER NOT NULL,
  TABLE_NAME    VARCHAR2(30),
  ACTION        VARCHAR2(10),
  LOGGED_ON     DATE DEFAULT SYSDATE
);

CREATE TABLE ORDER_APP.ORDERS_ARCHIVE (
  ORDER_ID      NUMBER NOT NULL,
  ARCHIVED_ON   DATE
);

ALTER TABLE ORDER_APP.ORDERS ADD CONSTRAINT ORDERS_CUSTOMER_FK
  FOREIGN KEY (CUSTOMER_ID) REFERENCES ORDER_APP.CUSTOMERS (CUSTOMER_ID);

ALTER TABLE ORDER_APP.ORDER_LINES ADD CONSTRAINT ORDER_LINES_ORDER_FK
  FOREIGN KEY (ORDER_ID) REFERENCES ORDER_APP.ORDERS (ORDER_ID);

CREATE INDEX ORDER_APP.ORDERS_CUSTOMER_IX ON ORDER_APP.ORDERS (CUSTOMER_ID);

CREATE SEQUENCE ORDER_APP.ORDER_SEQ;

CREATE SYNONYM ORDER_APP.CUST FOR ORDER_APP.CUSTOMERS;
